import { getAgentDisplayName } from "../mcp/agents.js";
import "../init/agents.js";
import { canPickAgentsInteractively } from "../utils/agent_picker.js";
import { NEON_SKILL_CATALOG } from "./catalog.js";
import prompts from "prompts";
//#region src/skills/wizard.ts
const restoreCursorOnAbort = (state) => {
	if (state.aborted) {
		process.stdout.write("\x1B[?25h");
		process.stdout.write("\n");
		process.exit(1);
	}
};
const pickSkillsInteractively = async () => {
	if (!canPickAgentsInteractively()) throw new Error("No interactive terminal. Pass -y to install the default skills into detected agents.");
	const { skills } = await prompts({
		onState: restoreCursorOnAbort,
		type: "multiselect",
		name: "skills",
		message: "Which Neon agent skills should be installed? (space to toggle, enter to confirm)",
		instructions: false,
		min: 1,
		choices: NEON_SKILL_CATALOG.map((entry) => ({
			value: entry,
			title: entry.skill,
			selected: entry.defaultSelected
		}))
	});
	if (!Array.isArray(skills) || skills.length === 0) throw new Error("No skills selected. Pass -y to install the default skills, or --skill <name>.");
	return skills.filter(isSkillEntry);
};
const isSkillEntry = (value) => {
	if (typeof value !== "object" || value === null) return false;
	if (!("source" in value) || !("skill" in value)) return false;
	return typeof value.source === "string" && typeof value.skill === "string" && value.source.length > 0 && value.skill.length > 0;
};
const skillsInstallSummary = (options) => {
	const skills = options.invocations.flatMap((invocation) => invocation.skills).join(", ");
	const rows = [
		["Config", options.scope === "project" ? "this directory" : "user-level"],
		["Agents", options.agents.map(getAgentDisplayName).join(", ")],
		["Skills", skills]
	];
	const labelWidth = Math.max(...rows.map(([label]) => label.length));
	return rows.map(([label, value]) => `${label.padEnd(labelWidth)}  ${value}`).join("\n");
};
const confirmSkillsInstall = async (options) => {
	if (!canPickAgentsInteractively()) return true;
	process.stdout.write(`\n${skillsInstallSummary(options)}\n\n`);
	const { ok } = await prompts({
		onState: restoreCursorOnAbort,
		type: "confirm",
		name: "ok",
		message: "Write Neon agent skills into these agents?",
		initial: true
	});
	return ok === true;
};
const confirmSkillsUpdate = async (options) => {
	if (!canPickAgentsInteractively()) return true;
	const config = options.scope === "project" ? "this directory" : "user-level";
	process.stdout.write(`\nConfig  ${config}\n\n`);
	const { ok } = await prompts({
		onState: restoreCursorOnAbort,
		type: "confirm",
		name: "ok",
		message: "Update installed skills to the latest versions?",
		initial: true
	});
	return ok === true;
};
//#endregion
export { confirmSkillsInstall, confirmSkillsUpdate, pickSkillsInteractively, skillsInstallSummary };
